class EnvVarCheck
{
    void CheckFlag()
    {
        // On Linux, set via: export MY_FLAG=""
        // .NET 9 breaking change: empty env vars are no longer treated as unset.
        // Use a helper to distinguish "not set" from "explicitly empty".
        var val = Environment.GetEnvironmentVariable("MY_FLAG");
        if (!IsEnvironmentVariableSet("MY_FLAG"))
        {
            Console.WriteLine("MY_FLAG not set, using default");
        }
    }

    /// <summary>
    /// Returns true if the variable exists in the environment (even if empty).
    /// In .NET 9, GetEnvironmentVariable returns "" for empty vars instead of null.
    /// To detect "not set", check the process environment block directly.
    /// </summary>
    static bool IsEnvironmentVariableSet(string name)
    {
        // In .NET 9, GetEnvironmentVariable("X") returns "" for export X=""
        // and null only when the variable is truly absent.
        return Environment.GetEnvironmentVariable(name) is not null;
    }
}

